//! Vault initialization and decryption commands.

use crate::state::AppState;

/// Initialize a new vault for a first-time user.
///
/// Generates a root folder AES-256 key and derives a deterministic Ed25519 IPNS
/// keypair via HKDF from the user's private key. ECIES-wraps them with the
/// user's secp256k1 public key, and POSTs everything to `/vault/init`.
pub(crate) async fn initialize_vault(state: &AppState, public_key: &[u8]) -> Result<(), String> {
    // Generate root folder AES-256 key (32 random bytes)
    let root_folder_key = cipherbox_crypto::utils::generate_random_bytes(32);

    // Derive IPNS keypairs from user's private key
    let private_key = state
        .sdk
        .private_key
        .read()
        .await
        .as_ref()
        .ok_or("Private key not available for vault IPNS derivation")?
        .clone();
    let private_key_arr: [u8; 32] = private_key
        .as_slice()
        .try_into()
        .map_err(|_| "Invalid private key length")?;

    // Root folder IPNS keypair (for folder metadata)
    let (root_ipns_private_key, _root_ipns_public_key, root_ipns_name) =
        cipherbox_crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
            .map_err(|e| format!("Vault IPNS derivation failed: {:?}", e))?;

    // Vault key IPNS keypair (for rootFolderKey blob — separate IPNS name)
    let (vault_key_ipns_private, _vault_key_ipns_public, vault_key_ipns_name) =
        cipherbox_crypto::hkdf::derive_vault_key_ipns_keypair(&private_key_arr)
            .map_err(|e| format!("Vault key IPNS derivation failed: {:?}", e))?;

    // ECIES-wrap rootFolderKey for v2 blob header
    let encrypted_root_folder_key = cipherbox_crypto::ecies::wrap_key(&root_folder_key, public_key)
        .map_err(|e| format!("Failed to wrap root folder key: {}", e))?;

    log::info!("Publishing vault key blob and root folder metadata");

    use base64::Engine;

    // 1. Publish v2 key blob to vault key IPNS (key only, no metadata)
    let blob_bytes = cipherbox_core::vault_blob::serialize_vault_blob_v2(&encrypted_root_folder_key)?;
    let key_blob_cid = cipherbox_api_client::ipfs::upload_content(&state.sdk.api, &blob_bytes).await.map_err(|e| e.to_string())?;

    let vault_key_ipns_arr: [u8; 32] = vault_key_ipns_private.as_slice()
        .try_into()
        .map_err(|_| "Invalid vault key IPNS private key length".to_string())?;
    let key_value = format!("/ipfs/{}", key_blob_cid);
    let key_record = cipherbox_core::ipns::create_ipns_record(&vault_key_ipns_arr, &key_value, 0, 86_400_000)
        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
    let key_marshaled = cipherbox_core::ipns::marshal_ipns_record(&key_record)
        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
    let key_record_base64 = base64::engine::general_purpose::STANDARD.encode(&key_marshaled);

    let key_publish_req = cipherbox_api_client::IpnsPublishRequest {
        ipns_name: vault_key_ipns_name,
        record: key_record_base64,
        metadata_cid: key_blob_cid,
        encrypted_ipns_private_key: None,
        key_epoch: None,
        expected_sequence_number: None,
    };
    match cipherbox_api_client::ipns::publish_ipns(&state.sdk.api, &key_publish_req).await.map_err(|e| e.to_string())? {
        cipherbox_api_client::PublishResult::Success => {}
        cipherbox_api_client::PublishResult::Conflict { .. } => {
            log::warn!("Unexpected conflict on vault key blob publish (sequence 0); aborting vault initialization to avoid mismatched root_folder_key");
            return Err("Vault initialization aborted due to existing vault key IPNS record".to_string());
        }
    }

    // 2. Publish folder metadata using v1 encrypted envelope format on IPFS ({iv, data});
    //    FolderMetadata.version remains "v2" (metadata schema version).
    let empty_metadata = cipherbox_core::folder::FolderMetadata {
        version: "v2".to_string(),
        children: vec![],
    };
    let folder_key_arr: [u8; 32] = root_folder_key
        .as_slice()
        .try_into()
        .map_err(|_| "Invalid root folder key length".to_string())?;
    let sealed = cipherbox_core::folder::encrypt_folder_metadata(&empty_metadata, &folder_key_arr)
        .map_err(|e| format!("Metadata encryption failed: {}", e))?;
    let iv_hex = hex::encode(&sealed[..12]);
    let data_base64 = base64::engine::general_purpose::STANDARD.encode(&sealed[12..]);
    let json_metadata = serde_json::json!({ "iv": iv_hex, "data": data_base64 });
    let json_bytes = serde_json::to_vec(&json_metadata)
        .map_err(|e| format!("JSON serialization failed: {}", e))?;
    let folder_cid = cipherbox_api_client::ipfs::upload_content(&state.sdk.api, &json_bytes).await.map_err(|e| e.to_string())?;

    let root_ipns_arr: [u8; 32] = root_ipns_private_key.as_slice()
        .try_into()
        .map_err(|_| "Invalid root IPNS private key length".to_string())?;
    let folder_value = format!("/ipfs/{}", folder_cid);
    let folder_record = cipherbox_core::ipns::create_ipns_record(&root_ipns_arr, &folder_value, 0, 86_400_000)
        .map_err(|e| format!("IPNS record creation failed: {}", e))?;
    let folder_marshaled = cipherbox_core::ipns::marshal_ipns_record(&folder_record)
        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
    let folder_record_base64 = base64::engine::general_purpose::STANDARD.encode(&folder_marshaled);

    let folder_publish_req = cipherbox_api_client::IpnsPublishRequest {
        ipns_name: root_ipns_name.clone(),
        record: folder_record_base64,
        metadata_cid: folder_cid,
        encrypted_ipns_private_key: None,
        key_epoch: None,
        expected_sequence_number: None,
    };
    match cipherbox_api_client::ipns::publish_ipns(&state.sdk.api, &folder_publish_req).await.map_err(|e| e.to_string())? {
        cipherbox_api_client::PublishResult::Success => {}
        cipherbox_api_client::PublishResult::Conflict { .. } => {
            log::warn!("Unexpected conflict on root folder publish (sequence 0)");
        }
    }

    // 3. Register vault with backend AFTER both IPNS records are durable
    let init_req = cipherbox_api_client::InitVaultRequest {
        owner_public_key: hex::encode(public_key),
        root_ipns_name: root_ipns_name.clone(),
    };

    let resp = state
        .sdk
        .api
        .authenticated_post("/vault/init", &init_req)
        .await
        .map_err(|e| format!("Vault init request failed: {}", e))?;

    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("Vault init failed ({}): {}", status, body));
    }

    log::info!("Vault initialized: key blob + root metadata published for new user");
    Ok(())
}

/// Fetch vault from backend and decrypt rootFolderKey from IPFS v2 blob.
///
/// All users read rootFolderKey from the IPFS vault blob v2 header.
/// The IPNS keypair is always HKDF-derived from the user's private key.
/// Stores all keys in AppState (memory only).
pub(crate) async fn fetch_and_decrypt_vault(state: &AppState) -> Result<(), String> {
    log::info!("Fetching and decrypting vault keys");

    // GET /vault
    let resp = state
        .sdk
        .api
        .authenticated_get("/vault")
        .await
        .map_err(|e| format!("Vault fetch failed: {}", e))?;

    if !resp.status().is_success() {
        let status = resp.status();
        let body = resp.text().await.unwrap_or_default();
        return Err(format!("Vault fetch failed ({}): {}", status, body));
    }

    let vault: cipherbox_api_client::VaultResponse = resp
        .json()
        .await
        .map_err(|e| format!("Failed to parse vault response: {}", e))?;

    // Get private key
    let private_key = state
        .sdk
        .private_key
        .read()
        .await
        .as_ref()
        .ok_or("Private key not available for vault decryption")?
        .clone();
    let private_key_arr: [u8; 32] = private_key
        .as_slice()
        .try_into()
        .map_err(|_| "Invalid private key length")?;

    // Derive root folder IPNS keypair (for folder operations)
    let (root_ipns_priv, _root_ipns_pub, _root_ipns_name) =
        cipherbox_crypto::hkdf::derive_vault_ipns_keypair(&private_key_arr)
            .map_err(|e| format!("HKDF derivation failed: {:?}", e))?;

    // Derive vault key IPNS keypair (for rootFolderKey blob)
    let (_vault_key_priv, _vault_key_pub, vault_key_ipns_name) =
        cipherbox_crypto::hkdf::derive_vault_key_ipns_keypair(&private_key_arr)
            .map_err(|e| format!("Vault key HKDF derivation failed: {:?}", e))?;

    // Resolve vault key IPNS, fetch v2 blob, extract rootFolderKey
    let resolved = cipherbox_api_client::ipns::resolve_ipns(&state.sdk.api, &vault_key_ipns_name)
        .await
        .map_err(|e| format!("Vault key IPNS resolve failed: {}", e))?;
    let blob_bytes = cipherbox_api_client::ipfs::fetch_content(&state.sdk.api, &resolved.cid)
        .await
        .map_err(|e| format!("IPFS fetch failed for vault key blob: {}", e))?;

    if cipherbox_core::vault_blob::detect_blob_version(&blob_bytes) != 2 {
        return Err("Vault key blob is not v2 format".into());
    }
    let enc_key = cipherbox_core::vault_blob::deserialize_vault_blob_v2(&blob_bytes)
        .map_err(|e| format!("v2 blob parse failed: {}", e))?;
    let root_folder_key = cipherbox_crypto::ecies::unwrap_key(enc_key, &private_key)
        .map_err(|e| format!("Failed to decrypt rootFolderKey from v2 blob: {}", e))?;

    // `unwrap_key` returns `Zeroizing<Vec<u8>>` (Phase 51 S3); the SDK-state field is
    // also `Zeroizing<Vec<u8>>`, so store it directly and keep the key wiped on drop.
    *state.sdk.root_folder_key.write().await = Some(root_folder_key);

    // Root folder IPNS key is HKDF-derived
    *state.sdk.root_ipns_private_key.write().await = Some(root_ipns_priv.to_vec());

    // Store IPNS name and TEE keys
    *state.sdk.root_ipns_name.write().await = Some(vault.root_ipns_name);
    *state.sdk.tee_keys.write().await = vault.tee_keys;

    log::info!("Vault keys decrypted and stored in memory");
    Ok(())
}

//! IPNS resolution and publishing via the CipherBox backend API.
//!
//! Resolves IPNS names to their current CID and sequence number,
//! and publishes signed IPNS records.

use crate::client::ApiClient;
use crate::error::ApiError;
use crate::types::{IpnsPublishRequest, IpnsResolveResponse, PublishResult};

/// Resolve an IPNS name to its current CID via the backend.
///
/// GET /ipns/resolve?ipnsName={name}
/// Returns the CID and sequence number of the current IPNS record.
pub async fn resolve_ipns(
    client: &ApiClient,
    ipns_name: &str,
) -> Result<IpnsResolveResponse, ApiError> {
    let path = format!("/ipns/resolve?ipnsName={}", urlencoding::encode(ipns_name));
    let resp = client.authenticated_get(&path).await?;

    if resp.status().as_u16() == 404 {
        return Err(ApiError::IpnsNotFound(ipns_name.to_string()));
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS resolve failed: {}", body),
        });
    }

    let status = resp.status().as_u16();
    let body: IpnsResolveResponse = resp
        .json()
        .await
        .map_err(|e| ApiError::DeserializationFailed(format!("IPNS resolve response: {}", e)))?;

    if !body.success || body.cid.is_empty() {
        return Err(ApiError::ApiResponse {
            status,
            message: format!(
                "IPNS resolve unsuccessful: success={}, cid='{}'",
                body.success, body.cid
            ),
        });
    }

    Ok(body)
}

/// Verify an IPNS resolve response signature.
///
/// Implements D-03 (absent fields → None, allow+warn), D-02 (invalid → Some(false)),
/// and D-04 (valid + name binding → Some(true)).
///
/// Returns:
/// - `Ok(None)` when any signature field is absent (legacy record, backward-compat).
/// - `Ok(Some(false))` when signature fields are present but verification fails or
///   the derived IPNS name does not match `ipns_name`.
/// - `Ok(Some(true))` when the signature is valid and the public key derives to `ipns_name`.
/// - `Err` when base64 decoding or IPNS name derivation fails on present fields.
pub fn verify_ipns_resolve_signature(
    resp: &crate::types::IpnsResolveResponse,
    ipns_name: &str,
) -> Result<Option<bool>, crate::error::ApiError> {
    use base64::engine::general_purpose::STANDARD;
    use base64::Engine as _;

    // D-03: absent fields → allow + flag (caller should warn and continue).
    let (Some(sig_b64), Some(data_b64), Some(pub_key_b64)) = (
        resp.signature_v2.as_ref(),
        resp.data.as_ref(),
        resp.pub_key.as_ref(),
    ) else {
        return Ok(None);
    };

    let decode_field = |label: &str, s: &str| -> Result<Vec<u8>, crate::error::ApiError> {
        STANDARD.decode(s).map_err(|e| {
            crate::error::ApiError::DeserializationFailed(format!(
                "IPNS {} base64 decode failed: {}",
                label, e
            ))
        })
    };
    let sig = decode_field("signatureV2", sig_b64)?;
    let cbor_data = decode_field("data", data_b64)?;
    let pub_key = decode_field("pubKey", pub_key_b64)?;

    // Build signed bytes: "ipns-signature:" prefix || CBOR data.
    let mut signed_data = b"ipns-signature:".to_vec();
    signed_data.extend_from_slice(&cbor_data);

    // D-02: invalid signature → fail closed.
    if !cipherbox_crypto::verify_ed25519(&signed_data, &sig, &pub_key) {
        return Ok(Some(false));
    }

    // Convert decoded pub_key to fixed 32-byte array; wrong length → treat as invalid.
    let pubkey_arr: [u8; 32] = match pub_key.as_slice().try_into() {
        Ok(arr) => arr,
        Err(_) => return Ok(Some(false)),
    };

    // Derive IPNS name and check it binds to the resolved name.
    let derived_name = cipherbox_crypto::derive_ipns_name(&pubkey_arr).map_err(|e| {
        crate::error::ApiError::DeserializationFailed(format!("IPNS name derivation failed: {}", e))
    })?;

    Ok(Some(derived_name == ipns_name))
}

/// Publish a signed IPNS record via the backend.
///
/// POST /ipns/publish with the signed record. The backend relays
/// to the delegated routing service and tracks the folder for TEE republishing.
///
/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
/// on 409 (another device published a higher sequence), or `Err` on
/// other errors.
pub async fn publish_ipns(
    client: &ApiClient,
    request: &IpnsPublishRequest,
) -> Result<PublishResult, ApiError> {
    let resp = client.authenticated_post("/ipns/publish", request).await?;

    if resp.status().as_u16() == 409 {
        // Parse conflict response body: { currentSequenceNumber: "..." }
        let body: serde_json::Value = resp.json().await.map_err(|e| {
            ApiError::DeserializationFailed(format!("409 Conflict but failed to parse body: {}", e))
        })?;
        let current_seq = body["currentSequenceNumber"]
            .as_str()
            .ok_or_else(|| {
                ApiError::DeserializationFailed(format!(
                    "409 Conflict but missing currentSequenceNumber in response: {}",
                    body
                ))
            })?
            .to_string();
        return Ok(PublishResult::Conflict {
            current_sequence_number: current_seq,
        });
    }

    if !resp.status().is_success() {
        let status = resp.status().as_u16();
        let body = resp.text().await.unwrap_or_default();
        return Err(ApiError::ApiResponse {
            status,
            message: format!("IPNS publish failed: {}", body),
        });
    }

    Ok(PublishResult::Success)
}

#[cfg(test)]
mod tests {
    use super::verify_ipns_resolve_signature;
    use crate::types::IpnsResolveResponse;
    use base64::engine::general_purpose::STANDARD;
    use base64::Engine as _;

    fn make_resolve_response_no_sig() -> IpnsResolveResponse {
        IpnsResolveResponse {
            success: true,
            cid: "bafytest".to_string(),
            sequence_number: "1".to_string(),
            signature_v2: None,
            data: None,
            pub_key: None,
        }
    }

    fn make_resolve_response_with_sig(
        signature_v2: &str,
        data: &str,
        pub_key: &str,
    ) -> IpnsResolveResponse {
        IpnsResolveResponse {
            success: true,
            cid: "bafytest".to_string(),
            sequence_number: "1".to_string(),
            signature_v2: Some(signature_v2.to_string()),
            data: Some(data.to_string()),
            pub_key: Some(pub_key.to_string()),
        }
    }

    /// Test 1: serde deserialization of optional sig fields.
    #[test]
    fn deserialize_with_sig_fields() {
        let json = r#"{
            "success": true,
            "cid": "bafytest",
            "sequenceNumber": "1",
            "signatureV2": "AAAA",
            "data": "BBBB",
            "pubKey": "CCCC"
        }"#;
        let resp: IpnsResolveResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.signature_v2, Some("AAAA".to_string()));
        assert_eq!(resp.data, Some("BBBB".to_string()));
        assert_eq!(resp.pub_key, Some("CCCC".to_string()));
    }

    /// Test 1b: serde deserialization without sig fields.
    #[test]
    fn deserialize_without_sig_fields() {
        let json = r#"{"success": true, "cid": "bafytest", "sequenceNumber": "1"}"#;
        let resp: IpnsResolveResponse = serde_json::from_str(json).unwrap();
        assert_eq!(resp.signature_v2, None);
        assert_eq!(resp.data, None);
        assert_eq!(resp.pub_key, None);
    }

    /// Test 2: absent sig fields → Ok(None) — D-03 allow+flag.
    #[test]
    fn absent_fields_returns_none() {
        let resp = make_resolve_response_no_sig();
        let result = verify_ipns_resolve_signature(&resp, "k51anyname");
        assert_eq!(result.unwrap(), None);
    }

    /// Test 3: invalid Ed25519 signature → Ok(Some(false)) — D-02.
    #[test]
    fn invalid_signature_returns_some_false() {
        let (pub_key_bytes, private_key) = cipherbox_crypto::generate_ed25519_keypair();
        let data_bytes = b"some-cbor-data";
        // Sign DIFFERENT bytes (wrong data) to create an invalid signature.
        let wrong_message = b"wrong-message";
        let sig_bytes = cipherbox_crypto::sign_ed25519(wrong_message, &private_key).unwrap();

        let resp = make_resolve_response_with_sig(
            &STANDARD.encode(&sig_bytes),
            &STANDARD.encode(data_bytes),
            &STANDARD.encode(&pub_key_bytes),
        );
        let ipns_name =
            cipherbox_crypto::derive_ipns_name(pub_key_bytes.as_slice().try_into().unwrap())
                .unwrap();
        let result = verify_ipns_resolve_signature(&resp, &ipns_name);
        assert_eq!(result.unwrap(), Some(false));
    }

    /// Test 4: valid signature and matching derived IPNS name → Ok(Some(true)) — D-04.
    #[test]
    fn valid_signature_matching_name_returns_some_true() {
        let (pub_key_bytes, private_key) = cipherbox_crypto::generate_ed25519_keypair();
        let data_bytes = b"some-cbor-data";

        // Build signed_data exactly as verify_ipns_resolve_signature expects.
        let mut signed_data = b"ipns-signature:".to_vec();
        signed_data.extend_from_slice(data_bytes);
        let sig_bytes = cipherbox_crypto::sign_ed25519(&signed_data, &private_key).unwrap();

        let pubkey_arr: [u8; 32] = pub_key_bytes.as_slice().try_into().unwrap();
        let ipns_name = cipherbox_crypto::derive_ipns_name(&pubkey_arr).unwrap();

        let resp = make_resolve_response_with_sig(
            &STANDARD.encode(&sig_bytes),
            &STANDARD.encode(data_bytes),
            &STANDARD.encode(&pub_key_bytes),
        );
        let result = verify_ipns_resolve_signature(&resp, &ipns_name);
        assert_eq!(result.unwrap(), Some(true));
    }

    /// Test 5: valid signature but IPNS name doesn't match derived name → Ok(Some(false)).
    #[test]
    fn valid_signature_wrong_name_returns_some_false() {
        let (pub_key_bytes, private_key) = cipherbox_crypto::generate_ed25519_keypair();
        let data_bytes = b"some-cbor-data";

        let mut signed_data = b"ipns-signature:".to_vec();
        signed_data.extend_from_slice(data_bytes);
        let sig_bytes = cipherbox_crypto::sign_ed25519(&signed_data, &private_key).unwrap();

        let resp = make_resolve_response_with_sig(
            &STANDARD.encode(&sig_bytes),
            &STANDARD.encode(data_bytes),
            &STANDARD.encode(&pub_key_bytes),
        );
        // Pass a deliberately wrong IPNS name.
        let result = verify_ipns_resolve_signature(&resp, "k51wrongname123");
        assert_eq!(result.unwrap(), Some(false));
    }
}

